import{_ as u,C as n,o as w,c as m,j as t,a,E as o,a8 as g}from"./chunks/framework.27XeWUA0.js";const s="/schedule-dashboard/thumbs/yt/T-42NrYjwxM-640.webp",b="/schedule-dashboard/thumbs/yt/T-42NrYjwxM-1280.webp",r="/schedule-dashboard/thumbs/yt/Sg6vtKOAOQ0-640.webp",v="/schedule-dashboard/thumbs/yt/Sg6vtKOAOQ0-1280.webp",i="/schedule-dashboard/thumbs/yt/MpkARD5pq-M-640.webp",f="/schedule-dashboard/thumbs/yt/MpkARD5pq-M-1280.webp",l="/schedule-dashboard/thumbs/yt/-uBABM2AuFg-640.webp",y="/schedule-dashboard/thumbs/yt/-uBABM2AuFg-1280.webp",h="/schedule-dashboard/thumbs/yt/0PqGT2L6cZM-640.webp",k="/schedule-dashboard/thumbs/yt/0PqGT2L6cZM-1280.webp",p="/schedule-dashboard/thumbs/yt/5UgnatzpZ9E-640.webp",A="/schedule-dashboard/thumbs/yt/5UgnatzpZ9E-1280.webp",j=JSON.parse('{"title":"AI Digest · Thu 05 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-05","routine":"digest"},"relativePath":"digest/2026-11-05.md","filePath":"digest/[date].md"}'),_={name:"digest/2026-11-05.md"},M=s+" 640w, "+b+" 1280w",T=r+" 640w, "+v+" 1280w",x=i+" 640w, "+f+" 1280w",I=l+" 640w, "+y+" 1280w",R=h+" 640w, "+k+" 1280w",q=p+" 640w, "+A+" 1280w",O={id:"ai-digest-·-thu-05-nov-2026",tabindex:"-1"};function B(N,e,D,S,L,E){const c=n("Badge"),d=n("DayFilter");return w(),m("div",null,[t("h1",O,[e[0]||(e[0]=a("AI Digest · Thu 05 Nov 2026 ",-1)),o(c,{type:"tip",text:"6"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-thu-05-nov-2026","aria-label":'Permalink to "AI Digest · Thu 05 Nov 2026 <Badge type="tip" text="6" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer daily digest — 5 Nov 2026 · run date Thu 05 Nov 2026 · 6 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(` 6 new talks in the last 24 hours, all with full transcripts. The freshest are Ramp's Alexander Shevchenko (5 Nov, 3:30 AM IST) on a post-trained Qwen model that beat Opus on finance tasks, KV-cache "cartridges" and a 10,000-agent pen test, and General Intuition's Pim de Witte (1:30 AM IST) on training robots from video-game recordings; both are worth your time. NatWest's talk has rare production numbers on LLM judges disagreeing with humans. Langfuse's bank-evals talk and Nous Research's open-source pitch are mostly repeats, and Datasite/Reducto is a useful buy-versus-build story.`)]),t("p",null,[t("strong",null,"Better Stack:"),a(" nothing new in the last 24 hours.")])],-1)),o(d),e[5]||(e[5]=g('<div class="grid cards2"><article class="it full" id="v-T-42NrYjwxM" data-title="Our Smaller Model Beat Opus on Finance Tasks - Alexander Shevchenko, Ramp" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=T-42NrYjwxM" target="_blank" rel="noopener"><img src="'+s+'" srcset="'+M+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=T-42NrYjwxM" target="_blank" rel="noopener">Our Smaller Model Beat Opus on Finance Tasks - Alexander Shevchenko, Ramp</a></h3><div class="meta">AI Engineer · Alexander Shevchenko, Ramp (Ramp Labs applied AI) · uploaded 5 Nov, 3:30 AM IST · 14:15</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — short, with three concrete production techniques (specialist model, cartridges, cheap-model swarms) rather than slogans.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 22 times before, &#39;token costs / AI spend&#39; 19 times, &#39;RL fine-tuning small models&#39; 6 times and &#39;AI-found vulnerabilities&#39; 4 times. New here: KV-cache &quot;cartridges&quot; prepared overnight for month-end close, a 10,000-agent pen-test swarm where open-weight models were up to 5x cheaper, and transferring a LoRA post-train across model versions.</div><div class="sh">Why an app company does research</div><ul><li><strong>Models keep getting cheaper:</strong> LLM use cases at Ramp are up 123% in a year, and top features spend more tokens overall but are cheaper per unit because each new frontier model is cheaper, faster and better (<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=60s" target="_blank" rel="noopener">1:00</a>)</li><li><strong>Why not just wait:</strong> In 2023 GPT-4 agents needed strict guardrails, couldn&#39;t backtrack and broke on synonyms, but Ramp shipped anyway (Ramp Tour Guide); agents are easy now, so the edge comes from digging a layer deeper (<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=60s" target="_blank" rel="noopener">1:00</a>–<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=180s" target="_blank" rel="noopener">3:00</a>)</li></ul><div class="sh">Three research bets sent to production</div><ul><li><strong>Specialist model beats Opus:</strong> Ramp Sheets (launched last November) spent ages planning and reading every sheet with slow, expensive Opus 4.6, so with Prime Intellect they post-trained a Qwen 3.5 35B financial question-answering model that beat Opus 4.6 on exact task accuracy at far lower latency, with the frontier model kept as orchestrator (<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li><li><strong>Cartridges (KV-cache compression):</strong> Compresses 20–30x more context into the KV cache offline, so for month-end close the ledger, aging report and documents can be pre-built overnight and the agent already &quot;knows&quot; them when the accountant opens it on the 1st; they&#39;d welcome labs shipping this in their APIs (<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=480s" target="_blank" rel="noopener">8:00</a>)</li><li><strong>10,000-agent pen test:</strong> Using their cloud agent Ramp Inspect, they ran 10,000 parallel agents over all of Ramp, de-duplicated and adversarially reproduced findings with LLMs, and patched 7 high-severity bugs, including a Lua script injection via email that no single component exposed; open-weight models up to 5x cheaper gave nearly the same detection rate in a swarm (<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=480s" target="_blank" rel="noopener">8:00</a>–<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=600s" target="_blank" rel="noopener">10:00</a>)</li></ul><div class="sh">Products and other research</div><ul><li><strong>Token spend management and Ramp Router:</strong> A product that maps LLM spend by key, user, accounting category and even tax credits with a semantic usage taxonomy, plus a router using strategies like Nvidia Switchyard and flex offloading to cut latency and cost (pitch) (<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=600s" target="_blank" rel="noopener">10:00</a>–<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=720s" target="_blank" rel="noopener">12:00</a>)</li><li><strong>Ramp Labs blog extras:</strong> &quot;Portal&quot; transfers a LoRA post-train to newer Qwen versions or other model families, self-improving Datadog monitors that adjust without a human, and open-ended semantic tagging of user sessions (<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=720s" target="_blank" rel="noopener">12:00</a>–<a href="https://www.youtube.com/watch?v=T-42NrYjwxM&amp;t=840s" target="_blank" rel="noopener">14:00</a>)</li></ul></div></article><article class="it full" id="v-Sg6vtKOAOQ0" data-title="AI Labs Will Trap You or Replace You - Dillon Rolnick, Nous Research" data-channel="AI Engineer" data-verdict="skip"><a class="th" href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skip">skip</span><h3><a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0" target="_blank" rel="noopener">AI Labs Will Trap You or Replace You - Dillon Rolnick, Nous Research</a></h3><div class="meta">AI Engineer · Dillon Rolnick, Nous Research (CEO) · uploaded 5 Nov, 2:30 AM IST · 15:13</div><div class="verdict v-skip"><b>Verdict:</b> skip — an opinion piece and Hermes Agent pitch; skim 2:00–6:00 if you want the lock-in argument.</div><div class="repeat">🔁 Repeat: &#39;open source / local models&#39; — seen 51 times before and &#39;vendor lock-in&#39; 5 times. New here: mostly an argument rather than data; the fresh bits are the claim that labs must either lock in businesses or compete with them directly (finance first), and that Nous cloned xAI&#39;s Grok bots UI into Hermes Agent in a weekend.</div><div class="sh">The labs&#39; incentive problem</div><ul><li><strong>Models are commoditizing:</strong> Practitioners switch freely between Astra, Fable, Opus and Kimi, and per-token prices fall while total token spend surges and serving costs stay flat, so margins on frontier models are narrowing (<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=60s" target="_blank" rel="noopener">1:00</a>–<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=120s" target="_blank" rel="noopener">2:00</a>)</li><li><strong>Two ways to earn back trillions:</strong> Move to another layer (infrastructure or the user, hence the fight at the agent layer), or &quot;build God&quot; and monetize it; businesses, not fickle consumers, are where the token money is (<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=120s" target="_blank" rel="noopener">2:00</a>–<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>Trap or replace:</strong> If ~70% of a company&#39;s output is agentic in 2–3 years and a lab controls those agents, it can change the rules and raise prices; or labs point their best models at lucrative problems like finance themselves, starting by hiring bankers and partnering with big firms (opinion) (<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li></ul><div class="sh">Nous&#39;s counter-pitch</div><ul><li><strong>Software moats are gone:</strong> Nous pointed Hermes Agent at xAI&#39;s Grok bots interface and reproduced it as an open-source Hermes feature in a weekend; Rolnick says future moats are network effects, reputation and reliability (<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=480s" target="_blank" rel="noopener">8:00</a>–<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=600s" target="_blank" rel="noopener">10:00</a>)</li><li><strong>Distillation framing:</strong> Labs call teaching one model from another &quot;illicit distillation&quot; and train models to refuse to help train other models, labelling that safety, which he calls self-serving (repeat) (<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=660s" target="_blank" rel="noopener">11:00</a>)</li><li><strong>Agents are operating systems:</strong> Agents combine deterministic code, data sources and model judgment like a framework, so build on a base where you can swap models and inherit improvements rather than maintain your own agent stack (<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=840s" target="_blank" rel="noopener">14:00</a>)</li><li><strong>Hermes Agent claim:</strong> He says Hermes Agent is the most-used and most-downloaded open-source agent, an order of magnitude ahead of close competitors (no figures shown) (<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=840s" target="_blank" rel="noopener">14:00</a>–<a href="https://www.youtube.com/watch?v=Sg6vtKOAOQ0&amp;t=913s" target="_blank" rel="noopener">15:13</a>)</li></ul></div></article><article class="it full" id="v-MpkARD5pq-M" data-title="Robots Will Be Trained on Video Games - Pim de Witte, General Intuition" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=MpkARD5pq-M" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=MpkARD5pq-M" target="_blank" rel="noopener">Robots Will Be Trained on Video Games - Pim de Witte, General Intuition</a></h3><div class="meta">AI Engineer · Pim de Witte, General Intuition (and Medal) · uploaded 5 Nov, 1:30 AM IST · 18:51</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a genuinely different take on robotics and computer use, though no demo video is shown.</div><div class="repeat">🔁 Repeat: &#39;training data pipelines&#39; — seen 5 times before. New here: nearly all of it; robotics and world models have come up only once before, and game recordings as robot training data is new.</div><div class="sh">The idea</div><ul><li><strong>Act while observing:</strong> Using Olaf from Frozen reassembling mid-roll as the example, de Witte argues turn-based next-token LLMs can&#39;t handle space and time, so purpose-built &quot;pixels in, actions out&quot; models fit robotics better (<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=120s" target="_blank" rel="noopener">2:00</a>)</li><li><strong>Games share robots&#39; action space:</strong> Medal, the video-game recorder, captures tens of thousands of games with controller inputs tied to frames; since many robots below a certain number of degrees of freedom ship with a game controller, the same actions transfer to teleoperation (<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=60s" target="_blank" rel="noopener">1:00</a>–<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>Skip predicting motor torque:</strong> Rather than predicting poses or motor values end-to-end like most robotics firms, the model outputs keyboard, mouse or controller actions, essentially an enhanced computer-use model, and the controller handles the physics (<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=240s" target="_blank" rel="noopener">4:00</a>–<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li></ul><div class="sh">The data bet</div><ul><li><strong>Scale:</strong> Medal gets about 1 billion uploads a year, on track for 3 billion, giving over 1.5 trillion action tokens a month; he says they collect in half a day what frontier labs use in total to train robotics models (<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li><li><strong>Action density:</strong> Gamers make far more actions per minute than teleoperators, which matters for jobs like drone flying with many small corrections; the model also learns the meaning of each action, helping interpretability (<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=480s" target="_blank" rel="noopener">8:00</a>–<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=600s" target="_blank" rel="noopener">10:00</a>)</li><li><strong>Versus V-JEPA:</strong> Meta&#39;s JEPA infers action labels instead of training on them; he calls it more correct in the limit but less practical, and says real action data (like rudder moves invisible in video) is their moat (<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=1020s" target="_blank" rel="noopener">17:00</a>–<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=1131s" target="_blank" rel="noopener">18:51</a>)</li></ul><div class="sh">Release and uses</div><ul><li><strong>One model, many bodies:</strong> One model plays games at top level and controls over 10 robot types in real time; early access over the next few months, release planned late November or early December, with hackathons in New York (mid-November) and London (<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=600s" target="_blank" rel="noopener">10:00</a>–<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=1020s" target="_blank" rel="noopener">17:00</a>)</li><li><strong>Use cases:</strong> Meant to sit under an orchestrator like Gemini or Astra for planning; ideas include exploring generated environments, UX testing as a human would, robot science labs, and accessibility (e.g. one-armed users playing games while the model handles the keyboard) (<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=MpkARD5pq-M&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li></ul></div></article><article class="it full" id="v--uBABM2AuFg" data-title="Don&#39;t Approve the AI Model. Approve the App - Doneyli De Jesus, Langfuse" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=-uBABM2AuFg" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+I+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=-uBABM2AuFg" target="_blank" rel="noopener">Don&#39;t Approve the AI Model. Approve the App - Doneyli De Jesus, Langfuse</a></h3><div class="meta">AI Engineer · Doneyli De Jesus, Langfuse (by ClickHouse) · uploaded 4 Nov, 3:30 PM IST · 19:20</div><div class="verdict v-skim"><b>Verdict:</b> skim from 7:00 — the calculator-tool fix and compliance-gate example are the useful parts; the rest restates familiar eval advice.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 54 times before, &#39;agent observability&#39; 30 times, &#39;human-in-the-loop review&#39; 29 times, &#39;AI in regulated industries&#39; 23 times, &#39;AI for finance&#39; 22 times and &#39;LLM-as-a-judge&#39; 11 times. New here: the top-5 bank numbers (97% groundedness but 60% numeric accuracy, fixed to about 95% with a calculator tool) and a binary regulatory-compliance gate that can block release on its own.</div><div class="sh">What the bank wanted</div><ul><li><strong>Certify apps, not models (repeat):</strong> The bank ignored public benchmarks; for a 10-K analyst for investment bankers, it wanted proof the application works on its own data, saying &quot;we don&#39;t certify models, we certify applications&quot; (<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>On-prem, gated, air-gapped:</strong> Banks are reopening data centers and standing up GPUs to run models locally, refuse even zero-retention API calls, and need air-gapped deployments (<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=300s" target="_blank" rel="noopener">5:00</a>)</li></ul><div class="sh">The gating method</div><ul><li><strong>Golden dataset as test cases (repeat):</strong> Inputs, expected outputs and metadata are run against the agent; traces become evidence and scores give pass or fail per dimension, re-run whenever the prompt, model or tools change (<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=660s" target="_blank" rel="noopener">11:00</a>)</li><li><strong>97% grounded, 60% on numbers:</strong> A model grounded 97% of answers in bank data but got financial numbers right only about 60% of the time; giving it a deterministic Python calculation tool lifted numeric accuracy to about 95% and cleared the bank&#39;s 85% gate (<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=780s" target="_blank" rel="noopener">13:00</a>)</li><li><strong>Mix scorers:</strong> Deterministic code checks, checks on the path the agent took, and LLM judges for qualitative parts, since LLM judges alone &quot;won&#39;t cut it&quot; (<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=780s" target="_blank" rel="noopener">13:00</a>)</li><li><strong>One dimension can block release:</strong> Across 150- and 1,500-question datasets, a config scored well on groundedness and completeness but zero on binary regulatory compliance, so averages hide it; risk experts set per-use-case thresholds (<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=780s" target="_blank" rel="noopener">13:00</a>–<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=960s" target="_blank" rel="noopener">16:00</a>)</li></ul><div class="sh">Closing the loop</div><ul><li><strong>Annotation queues:</strong> Compliance failures go to domain experts, and their reviewed traces feed back into the golden dataset; evaluation went from weeks or months to minutes, with a blog post and repo to reproduce (<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=960s" target="_blank" rel="noopener">16:00</a>–<a href="https://www.youtube.com/watch?v=-uBABM2AuFg&amp;t=1160s" target="_blank" rel="noopener">19:20</a>)</li></ul></div></article><article class="it full" id="v-0PqGT2L6cZM" data-title="Why Datasite Stopped Building Its Own Parsing - Adit Abraham, Reducto &amp; Raj Bakhru, Datasite" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=0PqGT2L6cZM" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+R+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=0PqGT2L6cZM" target="_blank" rel="noopener">Why Datasite Stopped Building Its Own Parsing - Adit Abraham, Reducto &amp; Raj Bakhru, Datasite</a></h3><div class="meta">AI Engineer · Adit Abraham (Reducto co-founder and CEO) with Raj Bakhru (Datasite global CTO), fireside chat · uploaded 4 Nov, 2:30 PM IST · 19:49</div><div class="verdict v-skim"><b>Verdict:</b> skim from 5:00 — good real-world buy-versus-build numbers, though it&#39;s partly a Reducto customer story.</div><div class="repeat">🔁 Repeat: &#39;AI for finance&#39; — seen 22 times before, &#39;document parsing&#39; 4 times and &#39;RAG pipelines&#39; 4 times. New here: Datasite&#39;s scale and its buy-versus-build reasoning, plus a 22% recall gain it credits to Reducto parsing.</div><div class="sh">Datasite&#39;s scale</div><ul><li><strong>Where M&amp;A data lives:</strong> About 60% of transactions over $100 million run through Datasite&#39;s virtual data rooms, with over a trillion tokens a year, 500,000+ monthly users, 55,000 data rooms a year and billions of pages (<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=240s" target="_blank" rel="noopener">4:00</a>)</li><li><strong>Why it bought Blue Flame:</strong> Bakhru&#39;s M&amp;A AI startup was a week from closing a VC round when Datasite, asked to put in $5 million, offered over dinner to buy the whole company; competitors had raised hundreds of millions, and data-room content plus Grata&#39;s 20 million private-company records gave proprietary data (<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=480s" target="_blank" rel="noopener">8:00</a>–<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=720s" target="_blank" rel="noopener">12:00</a>)</li></ul><div class="sh">Why they stopped building parsing</div><ul><li><strong>Everything is an edge case:</strong> Errors came from a pie-chart legend&#39;s shade of blue (the same data as a bar chart was read correctly), merged cells in finance spreadsheets, and XLSB or macro files; support time on these was huge (<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=480s" target="_blank" rel="noopener">8:00</a>)</li><li><strong>Spend engineers on revenue:</strong> With about 250 engineers and a goal of ~20% growth (about $200 million new revenue a year), he wants them on five revenue projects, not solved layers; he sees a &quot;barbell&quot; where senior and very junior engineers gain most from AI coding (<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=780s" target="_blank" rel="noopener">13:00</a>–<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=960s" target="_blank" rel="noopener">16:00</a>)</li></ul><div class="sh">Pipeline and results</div><ul><li><strong>The stack:</strong> Reducto runs inside Datasite&#39;s environment, handling bursts of up to a terabyte, then content goes to Turbopuffer as the vector database with graph RAG queries in Python on top (<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=1020s" target="_blank" rel="noopener">17:00</a>–<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=1080s" target="_blank" rel="noopener">18:00</a>)</li><li><strong>VDR Bench:</strong> A private benchmark of a few hundred questions over a data room of hundreds of documents, run on every change, which must beat dropping the same files into Claude or OpenAI projects; they credit Reducto parsing with 22% better recall and say most of the work is on extraction, not answering (<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=1080s" target="_blank" rel="noopener">18:00</a>–<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=1189s" target="_blank" rel="noopener">19:49</a>)</li><li><strong>Remaining friction:</strong> Getting cheaper models to stop tool-call spamming so they can move off pricier ones, while always optimizing quality first, then cost and speed (<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=960s" target="_blank" rel="noopener">16:00</a>–<a href="https://www.youtube.com/watch?v=0PqGT2L6cZM&amp;t=1020s" target="_blank" rel="noopener">17:00</a>)</li></ul></div></article><article class="it full" id="v-5UgnatzpZ9E" data-title="Building the AI Agent Is Easy. Proving It&#39;s Safe Isn&#39;t - Jonathan Osborne, NatWest" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=5UgnatzpZ9E" target="_blank" rel="noopener"><img src="'+p+'" srcset="'+q+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=5UgnatzpZ9E" target="_blank" rel="noopener">Building the AI Agent Is Easy. Proving It&#39;s Safe Isn&#39;t - Jonathan Osborne, NatWest</a></h3><div class="meta">AI Engineer · Jonathan Osborne, NatWest Group (lead AI engineer) · uploaded 4 Nov, 1:30 PM IST · 18:01</div><div class="verdict v-worth"><b>Verdict:</b> worth watching from 7:00 — the judge-calibration and human-agreement numbers are rare production data, even though the theme is familiar.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 54 times before, &#39;agent observability&#39; 30 times, &#39;human-in-the-loop review&#39; 29 times, &#39;AI in regulated industries&#39; 23 times and &#39;LLM-as-a-judge&#39; 11 times. New here: real bank numbers, including a judge with almost zero correlation to humans, humans agreeing only 64% on intent, and a 43% pass rate on topic changes.</div><div class="sh">Context and risk</div><ul><li><strong>Scale:</strong> NatWest has about 19 million UK retail customers, and its assistant Cora handles about 100,000 conversations a day, mostly scripted; about a third of journeys are moving to RAG answers and agents that can make payments or change addresses (<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=120s" target="_blank" rel="noopener">2:00</a>)</li><li><strong>Four new failure modes:</strong> Confidently wrong, talked into things via prompt injection, right but unhelpful, and non-deterministic, so years of scripted regression tests no longer apply (<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=180s" target="_blank" rel="noopener">3:00</a>–<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=300s" target="_blank" rel="noopener">5:00</a>)</li></ul><div class="sh">Shrink first, then measure</div><ul><li><strong>Routing funnel:</strong> A context filter removes about 20% of events like button clicks, deterministic rules route more, then a gated rephrasing step, a neural intent classifier over embeddings (not generative) and policy rules, all versioned config for audit and fallback (<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=300s" target="_blank" rel="noopener">5:00</a>–<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=420s" target="_blank" rel="noopener">7:00</a>)</li><li><strong>Quality as a vector:</strong> Scores split into safety, task and experience; a 94%-accurate router that&#39;s 100% confident when wrong is worse than an 85% one that knows its limits (<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=480s" target="_blank" rel="noopener">8:00</a>)</li><li><strong>Human validation:</strong> 111 payment-agent conversations over 37 journeys and 4 brands with 3 scorers each passed 83% overall, but 97% on happy paths, 76% on edge cases and only 43% on topic changes; humans agreed 95% on bias but only 64% on intent understanding (<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=420s" target="_blank" rel="noopener">7:00</a>–<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=600s" target="_blank" rel="noopener">10:00</a>)</li></ul><div class="sh">LLM judges in production</div><ul><li><strong>Generous judges are useless:</strong> On about 14,000 complaint cases scored by humans and a judge, the judge averaged 0.97 against humans&#39; 0.83 with almost no correlation; swapping only the judge model dropped scores sharply, so the judge model is part of the config, and they moved it to a different model family than the agent (<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=540s" target="_blank" rel="noopener">9:00</a>–<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=720s" target="_blank" rel="noopener">12:00</a>)</li><li><strong>Pipeline:</strong> OpenTelemetry/OpenInference traces, a 5% random sample plus every handoff, failure, long or angry chat, scoring every 4 hours, a hard CI/CD regression gate, Comet Opik for the agent and MPM for the classifier&#39;s drift, all air-gapped with no PII leaving (<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=660s" target="_blank" rel="noopener">11:00</a>–<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li><li><strong>Rollout:</strong> Shadow mode first (classify live traffic while scripts still answer), then brand-by-brand percentage rollout with feature flags that revert in seconds; complaint handlers must give feedback before rerunning an investigation (<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=840s" target="_blank" rel="noopener">14:00</a>–<a href="https://www.youtube.com/watch?v=5UgnatzpZ9E&amp;t=1081s" target="_blank" rel="noopener">18:01</a>)</li></ul></div></article></div>',1))])}const G=u(_,[["render",B]]);export{j as __pageData,G as default};
